      SUBROUTINE ROTATE(NPM)CC     CALCULATES TRANSFER MATRIX FOR ROTATION ELEMENTCC ----------------------------------------------------------------------      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8B.CIN'      INCLUDE 'ELM13A.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'ELM20.CIN'      INCLUDE 'R.CIN'      INTEGER         NPM      REAL            VM3, VM4C      NPM = 0      IF (NDIF .LT. 0) TH = - TH      TOTROT = TOTROT + TH      TOTRA = TOTRA + ABS(TH)      CSR = COS(TH)      IF (ABS(CSR) .LT. 0.00001) CSR = 0.0      SNR = SIN(TH)      IF (ABS(SNR) .LT. 0.00001 .AND. ABS(TH) .GT. 1.0) SNR = 0.0C     IF (ACCEL .AND. SNR .NE. 0.0 .AND. CSR .NE. 0.0) GO TO 140      IF ((ACCEL .OR. LTWISS) .AND. .NOT. REFER     1    .AND. SNR .NE. 0.0) GO TO 140      IF (REFER) THEN        IF (TYPE .EQ. 13) THEN          TOTROT = 0.0         ELSE          GO TO 100        ENDIF      ENDIF      IF (NORD1 .LT. 1) GO TO 10      R(4,4) = CSR      R(3,3) = CSR      R(2,2) = CSR      R(1,1) = CSR      R(2,4) = SNR      R(1,3) = SNR      R(4,2) = - SNR      R(3,1) = - SNRC   10 IF (.NOT. (ALIGN .OR. LAY)) GO TO 100      IF (RORC .LT. 3) GO TO 100      VM3 = R(3,1)*VM(1) + R(3,3)*VM(3)      VM(1) = R(1,1)*VM(1) + R(1,3)*VM(3)      VM(3) = VM3      VM4 = R(4,2)*VM(2) + R(4,4)*VM(4)      VM(2) = R(2,2)*VM(2) + R(2,4)*VM(4)      VM(4) = VM4      GO TO 100C  100 NPM = 1      GO TO 150  140 NPM = 4  150 RETURN      END